  for (const [id, skill] of [['2.2.1', 'A38'], ['2.2.2', 'A85'], ['2.2.3', 'A15'], ['2.2.4', 'A04'], ['2.2.4', 'A85'], ['2.2.4', 'D06'], ['2.2.4', 'D27'], ['2.3.2', 'D39'], ['2.3.3', 'D20'], ['2.3.4', 'D20']]) {
